<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {useRouter} from 'vue-router'
import {FolderPlus,Search} from 'lucide-vue-next'
import {useProjectStore} from '@/stores/project'
import {filterProjects} from '@/utils/project-view'
defineProps<{id:string}>()
const projects=useProjectStore(),router=useRouter(),query=ref('')
const visible=computed(()=>filterProjects(projects.items,{search:query.value,category:'',group:'',source:'',state:'',pinned:false,availability:'',sort:'recent'}))
onMounted(()=>{if(!projects.items.length&&!projects.loading)void projects.refresh()})
</script>
<template><aside class="ws ws-sidebar project-context-nav"><label class="project-nav-search"><Search :size="13"/><input v-model="query" :placeholder="$t('找项目…')" :aria-label="$t('查找侧栏项目')"/></label><p v-if="projects.error" class="ws-error">{{$systemMessage(projects.error)}}<button @click="projects.refresh">{{ $t("重试") }}</button></p><h2>{{ $t("进行中的事") }}</h2><button v-for="project in visible.filter(p=>p.state!=='archived')" :key="project.id" :class="{active:project.id===id}" :aria-current="project.id===id?'page':undefined" @click="router.push('/project/'+project.id)">{{project.name}}<small v-if="!project.available">{{ $t("位置失效") }}</small></button><template v-if="visible.some(p=>p.state==='archived')"><hr/><h2>{{ $t("已归档") }}</h2><button v-for="project in visible.filter(p=>p.state==='archived')" :key="project.id" :class="{active:project.id===id}" @click="router.push('/project/'+project.id)">{{project.name}}</button></template><small v-if="!visible.length&&!projects.loading">{{ $t("没有匹配项目") }}</small><button class="ws-settings" @click="router.push('/project')"><FolderPlus :size="15"/>{{ $t("管理项目") }}</button><small>{{ $t("一件事的来龙去脉") }}</small></aside></template>
<style>.project-context-nav{position:fixed;left:0;top:var(--titlebar-h);bottom:0;width:180px;z-index:1}.project-context-nav button{overflow-wrap:anywhere;min-height:38px;flex:none}.project-context-nav button small{font-size:10px;color:var(--danger)}.project-context-nav.ws-sidebar h2{font-size:12px;font-weight:500}.project-context-nav:has(~*){isolation:isolate}main.project-detail-tabs{padding-left:210px}.project-detail-tabs .pj-symbol-large{width:50px;height:50px;border-radius:9px}.project-detail-tabs .pj-detail-title h1{font-size:25px;margin:8px 0}.project-detail-tabs .pj-detail-header{gap:17px;margin-bottom:18px}.project-detail-tabs .pj-back{margin-bottom:18px}.project-nav-search{display:flex;align-items:center;gap:5px;border:1px solid var(--divider);border-radius:5px;padding:6px;margin:0 0 16px}.project-nav-search input{width:100%;min-width:0;font-size:12px;background:transparent;border:0;outline:none}:root:has(.source-return) .project-context-nav{top:calc(var(--titlebar-h) + 36px)}@media(max-width:1100px){.project-context-nav{width:150px}main.project-detail-tabs{padding-left:171px;padding-right:20px}}@media(max-width:800px){.project-context-nav{width:118px}main.project-detail-tabs{padding-left:131px;padding-right:12px}}</style>
